fields.InputDefinition:
{
  "goal": "Open the 'Events' entity grid — type 'Events' in the LEFT sidebar 'Search entities...' box and click the exact 'Events' node (or, if the search is giving you trouble, navigate directly to http://localhost:4200/app/data-explorer/Data?entity=Events). Click a row, then click 'Open Full Record'. Change the 'Location' text field to 'Temporary Edit 204'. An unsaved-changes banner appears at the TOP with a 'Save Changes' button and usually a 'Revert'/'Cancel'/'Discard' option. Do NOT save — instead discard the change (click Revert/Cancel/Discard, or navigate away and decline saving). Verify you end up with the change abandoned and no error (the field shows its original value, or you are back on a clean view). Pages can take 10-30s to load — wait, don't navigate away unexpectedly.",
  "startUrl": "http://localhost:4200/app/data-explorer/Data?entity=Events",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "A field was edited then the change was discarded/reverted without saving",
    "The app handled the discard cleanly (original value retained or clean navigation), no error",
    "No crash pages or stuck states"
  ]
}
